import{_ as e,a as o,b as a,c as i}from"./chunks/state-monitoring-4.bYFhpwI8.js";import{_ as n,o as r,c as s,a5 as l}from"./chunks/framework.DGp912Ge.js";const v=JSON.parse('{"title":"5. State Monitoring","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/common/state-monitoring.md","filePath":"guides/common/state-monitoring.md","lastUpdated":1785806767000}'),c={name:"guides/common/state-monitoring.md"};function d(p,t,g,m,h,u){return r(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-state-monitoring" tabindex="-1">5. State Monitoring <a class="header-anchor" href="#_5-state-monitoring" aria-label="Permalink to &quot;5. State Monitoring&quot;">​</a></h1><p><strong>Goal:</strong> Understand how to read the robot&#39;s real-time status panels in RBQGUI.</p><p>In RBQGUI, the State Monitoring view shows emergency status, battery level, sensor readings, and module health — all in one screen.</p><h2 id="top-status-bar" tabindex="-1">Top Status Bar <a class="header-anchor" href="#top-status-bar" aria-label="Permalink to &quot;Top Status Bar&quot;">​</a></h2><p>The top bar shows the <strong>EMERGENCY</strong> state indicator, battery voltage, connection status, and other system icons at a glance.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="Top status bar" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Top status bar — EMERGENCY, battery, connection indicators</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>If the <strong>EMERGENCY</strong> indicator is lit, stop all operation immediately and follow the <a href="/RBQ/guides/common/emo">Emergency Stop &amp; Recovery</a> procedure before continuing.</p></div></div><h2 id="joint-sensor-diagnostics" tabindex="-1">Joint &amp; Sensor Diagnostics <a class="header-anchor" href="#joint-sensor-diagnostics" aria-label="Permalink to &quot;Joint &amp; Sensor Diagnostics&quot;">​</a></h2><p>The diagnostics table shows per-joint values (temperature, position error, etc.) and IMU readings (gyro, acceleration) for every leg.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="Joint and sensor diagnostics table" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Joint/sensor diagnostics table</figcaption></figure><h3 id="joint-naming-convention" tabindex="-1">Joint naming convention <a class="header-anchor" href="#joint-naming-convention" aria-label="Permalink to &quot;Joint naming convention&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Abbreviation</th><th>Joint</th></tr></thead><tbody><tr><td>HRR / HRP / HRK</td><td>Hind Right — Roll / Pitch / Knee</td></tr><tr><td>HLR / HLP / HLK</td><td>Hind Left — Roll / Pitch / Knee</td></tr><tr><td>FRR / FRP / FRK</td><td>Front Right — Roll / Pitch / Knee</td></tr><tr><td>FLR / FLP / FLK</td><td>Front Left — Roll / Pitch / Knee</td></tr></tbody></table><h2 id="perception-module-status" tabindex="-1">Perception Module Status <a class="header-anchor" href="#perception-module-status" aria-label="Permalink to &quot;Perception Module Status&quot;">​</a></h2><p>This panel shows the on/off state of vision and sensor modules (IR projector, night vision, LED, buzzer, etc.) and reports operation/error/count values (Fail / Count).</p><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="Perception module status panel" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Perception module status</figcaption></figure><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>If a perception module shows <strong>OFF</strong> or reports errors, vision-based features such as RL (Vision Trot) mode may be unavailable or unreliable.</p></div></div><h2 id="power-switch-module-check" tabindex="-1">Power Switch &amp; Module Check <a class="header-anchor" href="#power-switch-module-check" aria-label="Permalink to &quot;Power Switch &amp; Module Check&quot;">​</a></h2><p>This panel displays power-switch states for the Vision Computer, cameras, LiDAR, and other peripherals, as well as load readings for BAT / LEGS / ADDON / EXTERN / CHARGE.</p><p>Use <strong>Reset</strong> to clear counters and <strong>Check</strong> to refresh status.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="Power switch and module health check panel" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Power switch &amp; module check</figcaption></figure><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>After verifying the robot is healthy, proceed to charge or pack it for storage:</p><ul><li><strong><a href="/RBQ/guides/common/charging.html">→ 6-1. Charging</a></strong></li><li><strong><a href="/RBQ/guides/common/packing.html">→ 6-2. Packing</a></strong></li><li><strong><a href="/RBQ/guides/common/emo.html">→ 6-3. Emergency Stop &amp; Recovery</a></strong></li></ul>',23)])])}const y=n(c,[["render",d]]);export{v as __pageData,y as default};
